export function sanitizeQuery(query: string): string {
  const safeChars = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 .-_@,;:()[]{}<>!$%^&*+=|\/?#%';
  return query.split('').filter(char => safeChars.includes(char)).join('');
}

export function safeGrep(pattern: string, file: string): void {
  const sanitizedPattern = sanitizeQuery(pattern);
  // Assuming `exec` is a function that executes the grep command
  exec(`grep ${sanitizedPattern} ${file}`);
}

