import { StepResult } from './types';

export function runLoop(step: () => StepResult, maxRetries: number = 5): StepResult {
  let retryCount = 0;
  while (retryCount < maxRetries) {
    const result = step();
    if (result.success) {
      return result;
    }
    retryCount++;
  }
  return { success: false, message: `Max retries (${maxRetries}) exceeded.` };
}

