import { test } from 'node:test';

export async function runTest(testSuite: string, timeout: number) {
  return new Promise<void>((resolve, reject) => {
    const testRunner = test.run(testSuite);
    testRunner.on('test start', () => {
      setTimeout(() => {
        testRunner.emit('test end', { result: { status: 'timeout' } });
        reject(new Error('Test execution timed out'));
      }, timeout);
    });
    testRunner.on('test end', (result) => {
      if (result.result.status === 'timeout') {
        reject(new Error('Test execution timed out'));
      } else {
        resolve();
      }
    });
  });
}

